const PROVIDER_ICONS = {
  anilist: 'mdi-animation-play-outline', spotify: 'mdi-spotify', applemusic: 'mdi-apple',
  netease: 'mdi-music-circle-outline', qqmusic: 'mdi-music-note-circle',
  douban: 'mdi-movie-open-outline', maoyan: 'mdi-ticket-confirmation-outline', popular: 'mdi-fire',
  mikan: 'mdi-television-classic', netflix: 'mdi-play-box-outline',
};

const loading = ref(true);
const saving = ref(false);
const error = ref('');
const configurationBlocked = ref(true);
const providerIssues = reactive({});
const preservedProviders = reactive({});
const resetTarget = ref('');
const resetBusy = ref(false);
const resetError = ref('');
let configLoadPromise = null;
let configurationLoaded = false;
const providerSpecs = ref([]);
const activeGroup = ref(GLOBAL_KEY);
const running = reactive({});
const testing = reactive({});          // provider_id -> 连通性测试进行中
const testCooldown = reactive({});     // provider_id -> 冷却截止时间戳(ms)，防抖/防疯狂点击
const showAdvanced = reactive({});
const runMsg = reactive({ pid: '', text: '', ok: true });
const snapshot = ref(null);

// 左侧导航收起（仅图标）—— 记忆到本地存储，跨会话保持
const navCollapsed = ref(readCollapsed());
function readCollapsed() {
  try { return localStorage.getItem('asa.navCollapsed') === '1' } catch { return false }
}
function toggleNav() {
  navCollapsed.value = !navCollapsed.value;
  try { localStorage.setItem('asa.navCollapsed', navCollapsed.value ? '1' : '0'); } catch { /* ignore */ }
}

// 移动端（容器 < 680px，与窗口式导航同一断点）禁用「仅图标」折叠：功能栏始终完整显示。
// 用 ResizeObserver 监听布局容器宽度（贴合 CSS 容器查询语义）。
const layoutRef = ref(null);
const isNarrow = ref(false);
const asideOpen = ref(false);  // 移动端「概览」右侧抽屉开合（桌面端概览常驻右列，不使用此状态）
let navRO = null;
onMounted(() => {
  if (typeof ResizeObserver === 'undefined' || !layoutRef.value) return
  navRO = new ResizeObserver(entries => {
    for (const e of entries) isNarrow.value = (e.contentRect?.width || 0) < 680;
    if (!isNarrow.value && asideOpen.value) asideOpen.value = false;  // 切回桌面自动收起抽屉
  });
  navRO.observe(layoutRef.value);
});
onUnmounted(() => { if (navRO) { navRO.disconnect(); navRO = null; } });

// 显式点击在当前配置窗口中切换，不持久保存入口页签。
const tabDefs = computed(() => [
  { key: 'history', label: t('navHistory'), icon: 'mdi-history' },
  { key: 'manage', label: t('navManage'), icon: 'mdi-bell-cog-outline' },
  { key: 'blacklist', label: t('navBlacklist'), icon: 'mdi-cancel' },
  { key: 'config', label: t('navConfig'), icon: 'mdi-cog-outline' },
]);
const navigationView = ref('');
function onTab(key) {
  if (['history', 'manage', 'blacklist'].includes(key)) navigationView.value = key;
}

// 移动端窗口式导航：先展示功能栏，点选渠道后进入对应配置页，返回回到功能栏（桌面端不影响）
const mobileView = ref('nav'); // 'nav' | 'content'
function selectGroup(key) {
  activeGroup.value = key;
  mobileView.value = 'content';
}

// 运行概览（订阅历史粗略统计）+ 处理中运行态，来自 /status
const summaryState = ref('loading'); // loading | available | unavailable
const stats = ref(null);
const runState = ref([]); // [{provider_id, name, processed, started}]（运行中的来源）
let pollTimer = null;
// 轮询靠自身重排，只在卸载时 clearTimeout 拦不住它：若卸载发生在请求挂起期间，
// 响应回来后还会再排一次，留下一个谁也管不到的孤儿循环。故用此标记一并封住重排入口。
let disposed = false;
function armPoll(ms) {
  clearTimeout(pollTimer);
  if (disposed) return
  pollTimer = setTimeout(loadStatus, ms);
}
async function loadStatus() {
  if (disposed) return
  try {
    if (!props.api || typeof props.api.get !== 'function') throw new Error('no api')
    const res = await props.api.get(`${PLUGIN}/status?lang=${encodeURIComponent(locale.value)}`);
    if (disposed) return
    const s = res && res.stats ? res.stats : null;
    stats.value = s;
    summaryState.value = s ? 'available' : 'unavailable';
    runState.value = Array.isArray(res && res.running) ? res.running : [];
    // 有运行中的来源则持续轮询，直至全部结束
    if (runState.value.length) armPoll(2500);
  } catch {
    if (disposed) return
    stats.value = null;
    summaryState.value = 'unavailable';
    runState.value = [];
  }
}
onUnmounted(() => { disposed = true; clearTimeout(pollTimer); });
const overviewRows = computed(() => {
  const by = (stats.value && stats.value.by_status) || {};
  return [
    { key: 'subscribed', icon: 'mdi-check-circle-outline', color: 'success', n: by.subscribed || 0 },
    { key: 'media_exists', icon: 'mdi-database-check-outline', color: 'info', n: by.media_exists || 0 },
    { key: 'subscription_exists', icon: 'mdi-bell-check-outline', color: 'primary', n: by.subscription_exists || 0 },
    { key: 'filtered', icon: 'mdi-filter-remove-outline', color: 'warning', n: by.filtered || 0 },
  ]
});
const totalHandled = computed(() => (stats.value && stats.value.total) || 0);

function deepClone(obj) { try { return JSON.parse(JSON.stringify(obj ?? {})) } catch { return {} } }

const initClone = deepClone(props.initialConfig);
const config = reactive({
  global: Object.fromEntries(Object.entries(GLOBAL_DEFAULTS).map(([key, value]) => [key, initClone.global?.[key] ?? value])),
  providers: initClone.providers && typeof initClone.providers === 'object' && !Array.isArray(initClone.providers) ? initClone.providers : {},
});

const globalSections = computed(() => GLOBAL_SECTIONS.map(s => ({
  title: t(s.titleKey),
  fields: s.fields.map(f => ({ key: f.key, kind: f.kind, label: t(`g.${f.key}.label`), hint: t(`g.${f.key}.hint`) })),
})));

const PROVIDER_ORDER = ['douban', 'maoyan', 'popular', 'mikan', 'netflix', 'anilist', 'spotify', 'applemusic', 'netease', 'qqmusic'];
const MUSIC_PROVIDERS = new Set(['spotify', 'applemusic', 'netease', 'qqmusic']);
const groups = computed(() => {
  const order = pid => {
    const index = PROVIDER_ORDER.indexOf(pid);
    return index < 0 ? PROVIDER_ORDER.length : index
  };
  const providers = [...providerSpecs.value].sort((a, b) => order(a.provider_id) - order(b.provider_id));
  const sections = [
    { key: 'media', name: t('mediaSources'), items: providers.filter(s => !MUSIC_PROVIDERS.has(s.provider_id)) },
    { key: 'music', name: t('musicSources'), items: providers.filter(s => MUSIC_PROVIDERS.has(s.provider_id)) },
  ];
  return [
    { key: GLOBAL_KEY, name: t('globalHeading'), icon: 'mdi-tune-variant' },
    ...sections.filter(section => section.items.length).flatMap(section => [
      { key: `section:${section.key}`, name: section.name, heading: true },
      ...section.items.map(s => ({ key: s.provider_id, name: s.provider_name || s.provider_id, icon: groupIcon(s.provider_id) })),
    ]),
  ]
});
const activeSpec = computed(() => providerSpecs.value.find(s => s.provider_id === activeGroup.value) || null);
const enabledCount = computed(() => providerSpecs.value.filter(s => isProviderEnabled(s.provider_id)).length);
const notifyingCount = computed(() => providerSpecs.value.filter(s => config.providers[s.provider_id]?.notify).length);

const changedCount = computed(() => {
  if (!snapshot.value) return 0
  const cur = flatten(configurationPayload());
  const base = snapshot.value;
  let n = 0;
  const keys = new Set([...Object.keys(cur), ...Object.keys(base)]);
  keys.forEach(k => { if (cur[k] !== base[k]) n++; });
  return n
});
function configurationPayload() {
  const payload = deepClone(config);
  for (const [pid, original] of Object.entries(preservedProviders)) payload.providers[pid] = original === null ? null : deepClone(original);
  return payload
}
function flatten(obj, prefix = '', out = {}) {
  if (obj === null || typeof obj !== 'object' || Array.isArray(obj)) { out[prefix] = JSON.stringify(obj); return out }
  for (const [k, v] of Object.entries(obj)) flatten(v, prefix ? `${prefix}.${k}` : k, out);
  return out
}

function groupIcon(pid) { return PROVIDER_ICONS[pid] || 'mdi-rss' }
function isProviderEnabled(pid) { return !!(config.providers[pid] && config.providers[pid].enabled) }

function ensureProviderConfig(spec) {
  const pid = spec.provider_id;
  const existed = pid in config.providers;
  const raw = config.providers[pid];
  const ruleField = (spec.options_schema || []).find(f => f.kind === 'rule-list');
  if (existed && (providerIssues[pid] || !raw || typeof raw !== 'object' || Array.isArray(raw) ||
      (ruleField && !Array.isArray(raw.options?.[ruleField.key])))) {
    if (!(pid in preservedProviders)) preservedProviders[pid] = raw === null ? null : deepClone(raw);
    providerIssues[pid] ||= `${spec.provider_name || pid}：配置异常，原配置已保留，仅暂停此来源`;
    config.providers[pid] = defaultProvider(spec);
    return
  }
  if (!config.providers[pid] || typeof config.providers[pid] !== 'object') config.providers[pid] = {};
  const pc = config.providers[pid];
  if (typeof pc.enabled !== 'boolean') pc.enabled = false;
  if (typeof pc.notify !== 'boolean') pc.notify = false;
  if (!pc.cron) pc.cron = spec.default_cron || '';
  if (!pc.options || typeof pc.options !== 'object') pc.options = {};
  if (!pc.filters || typeof pc.filters !== 'object') pc.filters = {};
  pc.options = { ...pc.options, ...Object.fromEntries((spec.options_schema || []).map(f => [f.key, pc.options[f.key] === undefined ? deepClone(f.default) : pc.options[f.key]])) };
  pc.filters = { ...pc.filters, ...Object.fromEntries((spec.filters_schema || []).map(f => [f.key, pc.filters[f.key] === undefined ? deepClone(f.default) : pc.filters[f.key]])) };
}

function defaultProvider(spec) {
  return { enabled: false, notify: false, cron: spec.default_cron || '',
    options: Object.fromEntries((spec.options_schema || []).map(f => [f.key, deepClone(f.default)])),
    filters: Object.fromEntries((spec.filters_schema || []).map(f => [f.key, deepClone(f.default)])) }
}

async function restoreDefaults() {
  resetBusy.value = true;
  resetError.value = '';
  try {
    if (resetTarget.value !== 'all') {
      const spec = providerSpecs.value.find(s => s.provider_id === resetTarget.value);
      if (!spec) throw new Error(t('providersError'))
      config.providers[spec.provider_id] = defaultProvider(spec);
      delete preservedProviders[spec.provider_id];
      delete providerIssues[spec.provider_id];
    } else {
      if (typeof props.api?.post !== 'function') throw new Error(t('apiUnavailable'))
      const response = await props.api.post(`${PLUGIN}/config/reset`, { confirmed: true });
      if (response?.code !== 0 || !response?.config) throw new Error(response?.message || t('restoreFailed'))
      config.global = deepClone(response.config.global || GLOBAL_DEFAULTS);
      config.providers = deepClone(response.config.providers || {});
      for (const key of Object.keys(providerIssues)) delete providerIssues[key];
      for (const key of Object.keys(preservedProviders)) delete preservedProviders[key];
      providerSpecs.value.forEach(ensureProviderConfig);
      configurationBlocked.value = false;
      configurationLoaded = true;
      configLoadPromise = Promise.resolve();
      snapshot.value = flatten(configurationPayload());
      error.value = '';
    }
    resetTarget.value = '';
  } catch (e) { resetError.value = e?.message || String(e); }
  finally { resetBusy.value = false; }
}

async function loadProviders() {
  loading.value = true;
  error.value = '';
  try {
    if (!props.api || typeof props.api.get !== 'function') throw new Error(t('apiUnavailable'))
    // 来源元数据不依赖配置请求，配置损坏也必须能显示完整来源导航与恢复入口。
    const res = await props.api.get(`${PLUGIN}/providers?lang=${encodeURIComponent(locale.value)}`);
    providerSpecs.value = Array.isArray(res) ? res : (Array.isArray(res?.providers) ? res.providers : []);
    if (!providerSpecs.value.length) throw new Error(t('providersError'))
    // 宿主传入的 initialConfig 可能早于插件启动迁移；只在首次载入时读取后端的已升级配置。
    // 语言切换复用该请求，避免覆盖用户尚未保存的编辑。
    if (!configLoadPromise) configLoadPromise = (async () => {
      const response = await props.api.get(`${PLUGIN}/config`);
      if (!response?.config || typeof response.config !== 'object' || Array.isArray(response.config)) {
        throw new Error(response?.message || '无法读取升级后的配置，已阻止保存')
      }
      config.global = { ...config.global, ...deepClone(response.config.global || {}) };
      const sources = deepClone(response.config.providers || {});
      if (typeof sources !== 'object' || Array.isArray(sources)) throw new Error('来源配置格式异常，可还原全部默认配置')
      config.providers = sources;
      Object.assign(providerIssues, response.provider_errors || {});
      if (response.warning || response.code) error.value = response.warning || response.message;
      configurationLoaded = true;
    })();
    await configLoadPromise;
    providerSpecs.value.forEach(ensureProviderConfig);
    configurationBlocked.value = false;
    if (!snapshot.value) snapshot.value = flatten(configurationPayload());
  } catch (e) {
    error.value = e?.message || String(e);
    configurationBlocked.value = true;
    if (!configurationLoaded) configLoadPromise = null;
    // 初始快照只供显示；读取配置失败时禁止普通保存，但仍可调用维护恢复接口。
    providerSpecs.value.forEach(ensureProviderConfig);
  }
  loading.value = false;
}

// 语言切换时仅刷新来源标签（重新拉取本地化 spec），不重置脏值基线
watch(locale, () => { loadProviders(); });

function visibleFilters(spec) { return (spec.filters_schema || []).filter(f => f.kind !== 'hidden') }
function normalOptions(spec) { return (spec.options_schema || []).filter(f => f.advanced !== true) }
function advancedOptions(spec) { return (spec.options_schema || []).filter(f => f.advanced === true) }
function normalFilters(spec) { return visibleFilters(spec).filter(f => f.advanced !== true) }
function advancedFilters(spec) { return visibleFilters(spec).filter(f => f.advanced === true) }
function hasAdvanced(spec) { return advancedOptions(spec).length > 0 || advancedFilters(spec).length > 0 }
function toggleAdvanced(pid) { showAdvanced[pid] = !showAdvanced[pid]; }

function rowClass(field) {
  return ['asa-row', {
    'asa-row--switch': field.kind === 'switch',
    'asa-row--wide': ['textarea', 'rule-list'].includes(field.kind),
  }]
}

async function runProvider(pid) {
  running[pid] = true;
  runMsg.pid = pid;
  runMsg.text = '';
  try {
    if (!props.api || typeof props.api.post !== 'function') throw new Error(t('apiUnavailable'))
    const res = await props.api.post(`${PLUGIN}/run`, { provider_id: pid });
    runMsg.ok = true;
    runMsg.text = (res && res.message) || t('runTriggered');
    // 3 秒后开始运行，稍后轮询运行态以显示「处理中」
    armPoll(3500);
  } catch (e) {
    runMsg.ok = false;
    runMsg.text = t('runFailed') + (e?.message || e);
  } finally {
    running[pid] = false;
  }
}

// 连通性测试：抓取来源前几条验证连通（后端不订阅、不写历史）。前端防抖：进行中禁用 + 冷却期忽略，
// 双保险配合后端最小间隔，避免疯狂点击/短时间高频触发。
async function testProvider(pid) {
  const now = Date.now();
  if (testing[pid]) return
  if (now < (testCooldown[pid] || 0)) {
    runMsg.pid = pid; runMsg.ok = false; runMsg.text = t('throttled');
    return
  }
  testCooldown[pid] = now + 2000;
  testing[pid] = true;
  runMsg.pid = pid; runMsg.text = '';
  try {
    if (!props.api || typeof props.api.post !== 'function') throw new Error(t('apiUnavailable'))
    const res = await props.api.post(`${PLUGIN}/providers/test`, { provider_id: pid });
    if (res && res.throttled) { runMsg.ok = false; runMsg.text = (res && res.message) || t('throttled'); }
    else { runMsg.ok = !!(res && res.ok); runMsg.text = (res && res.message) || (runMsg.ok ? t('testOk') : t('testFail')); }
  } catch (e) {
    runMsg.ok = false;
    runMsg.text = t('testFail') + (e?.message || e);
  } finally {
    testing[pid] = false;
    testCooldown[pid] = Date.now() + 2000;
  }
}

// 定时表达式必须是五段，且每段只含数字与 * , - / 这些合法字符。这里只挡住明显写错的
// 输入，真正的语义校验仍由后端 CronTrigger 负责——放非法值过去的话，后端只会静静地跳过
// 该来源，界面上看不出任何异常，用户只会发现定时任务再也不触发了。
const CRON_SEGMENT = /^[\d*,\-/]+$/;
function cronError(expr) {
  const value = (expr || '').trim();
  if (!value) return ''
  const parts = value.split(/\s+/);
  if (parts.length !== 5 || !parts.every(p => CRON_SEGMENT.test(p))) return t('cronInvalid')
  return ''
}
const activeCronError = computed(() => {
  const group = config.providers && config.providers[activeGroup.value];
  return group ? cronError(group.cron) : ''
});
// 哪些来源的 cron 写错了，保存前据此拦截并指名道姓。
const cronErrors = computed(() => Object.entries(config.providers || {})
  .filter(([, conf]) => conf && cronError(conf.cron))
  .map(([pid]) => {
    const spec = providerSpecs.value.find(s => s.provider_id === pid);
    return (spec && spec.provider_name) || pid
  }));

function saveConfig() {
  if (loading.value || configurationBlocked.value) return
  if (cronErrors.value.length) {
    error.value = `${t('cronInvalid')}：${cronErrors.value.join('、')}`;
    return
  }
  saving.value = true;
  try {
    const payload = configurationPayload();
    emit('save', payload);
    snapshot.value = flatten(payload);
  } finally {
    saving.value = false;
  }
}

onMounted(() => { loadProviders(); loadStatus(); });

